use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl TypeParam { pub fn merge (self) -> TypeOrConstParam { TypeOrConstParam { id : self . id . into () } } pub fn name (self , db : & dyn HirDatabase) -> Name { self . merge () . name (db) } pub fn parent (self , _db : & dyn HirDatabase) -> GenericDef { self . id . parent () . into () } pub fn module (self , db : & dyn HirDatabase) -> Module { self . id . parent () . module (db) . into () } # [doc = " Is this type parameter implicitly introduced (eg. `Self` in a trait or an `impl Trait`"] # [doc = " argument)?"] pub fn is_implicit (self , db : & dyn HirDatabase) -> bool { let params = db . generic_params (self . id . parent ()) ; let data = & params [self . id . local_id ()] ; match data . type_param () . unwrap () . provenance { TypeParamProvenance :: TypeParamList => false , TypeParamProvenance :: TraitSelf | TypeParamProvenance :: ArgumentImplTrait => true , } } pub fn ty (self , db : & dyn HirDatabase) -> Type < '_ > { let resolver = self . id . parent () . resolver (db) ; let interner = DbInterner :: new_with (db , None , None) ; let index = hir_ty :: param_idx (db , self . id . into ()) . unwrap () ; let ty = Ty :: new_param (interner , self . id , index as u32) ; Type :: new_with_resolver_inner (db , & resolver , ty) } # [doc = " FIXME: this only lists trait bounds from the item defining the type"] # [doc = " parameter, not additional bounds that might be added e.g. by a method if"] # [doc = " the parameter comes from an impl!"] pub fn trait_bounds (self , db : & dyn HirDatabase) -> Vec < Trait > { let self_ty = self . ty (db) . ty ; GenericPredicates :: query_explicit (db , self . id . parent ()) . iter_identity_copied () . filter_map (| pred | match & pred . kind () . skip_binder () { ClauseKind :: Trait (trait_ref) if trait_ref . self_ty () == self_ty => { Some (Trait :: from (trait_ref . def_id () . 0)) } _ => None , }) . collect () } pub fn default (self , db : & dyn HirDatabase) -> Option < Type < '_ > > { let ty = generic_arg_from_param (db , self . id . into ()) ? ; let resolver = self . id . parent () . resolver (db) ; match ty { GenericArg :: Ty (it) if ! it . is_ty_error () => { Some (Type :: new_with_resolver_inner (db , & resolver , it)) } _ => None , } } pub fn is_unstable (self , db : & dyn HirDatabase) -> bool { db . attrs (GenericParamId :: from (self . id) . into ()) . is_unstable () } }
}